create table RB_LOAN_FUND_INFO (INTERNAL_KEY INT not null  ,CLIENT_NO VARCHAR(22) not null  ,LOAN_LENDERS_AMT DECIMAL(17,2) null  ,LOAN_LENDERS_NOT_USE_AMT DECIMAL(17,2) null  ,COMPANY VARCHAR(20) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  , primary key(INTERNAL_KEY,CLIENT_NO));